import os
import sqlite3

from flask import Flask, request, redirect, url_for, render_template, flash
from flask_login import (
    LoginManager, UserMixin, current_user,
    login_required, login_user, logout_user,
)
from werkzeug.security import check_password_hash

app = Flask(__name__)
app.config["SECRET_KEY"] = os.environ["SECRET_KEY"]  # Set a long, random value in your environment
app.config["SESSION_COOKIE_HTTPONLY"] = True
app.config["SESSION_COOKIE_SAMESITE"] = "Lax"
# Enable this when the app is served over HTTPS:
app.config["SESSION_COOKIE_SECURE"] = True

login_manager = LoginManager()
login_manager.init_app(app)
login_manager.login_view = "login"


class User(UserMixin):
    def __init__(self, user_id, username):
        self.id = str(user_id)
        self.username = username


def get_db():
    conn = sqlite3.connect("budget_tracker.db")
    conn.row_factory = sqlite3.Row
    return conn


@login_manager.user_loader
def load_user(user_id):
    conn = get_db()
    try:
        row = conn.execute(
            "SELECT id, username FROM users WHERE id = ?", (user_id,)
        ).fetchone()
        return User(row["id"], row["username"]) if row else None
    finally:
        conn.close()


@app.route("/login", methods=["GET", "POST"])
def login():
    if current_user.is_authenticated:
        return redirect(url_for("dashboard"))

    if request.method == "POST":
        username = request.form.get("username", "").strip()
        password = request.form.get("password", "")

        if not username or not password:
            flash("Enter your username and password.")
            return render_template("login.html"), 400

        conn = get_db()
        try:
            row = conn.execute(
                "SELECT id, username, password_hash FROM users WHERE username = ?",
                (username,),
            ).fetchone()
        finally:
            conn.close()

        if row and check_password_hash(row["password_hash"], password):
            login_user(User(row["id"], row["username"]), remember=False)
            # In production, validate any `next` URL before redirecting to it.
            return redirect(url_for("dashboard"))

        flash("Invalid username or password.")

    return render_template("login.html"), 401 if request.method == "POST" else 200


@app.route("/logout", methods=["POST"])
@login_required
def logout():
    logout_user()
    return redirect(url_for("login"))


@app.route("/dashboard")
@login_required
def dashboard():
    return render_template("dashboard.html", username=current_user.username)


if __name__ == "__main__":
    app.run(debug=False)
